package com.weaponsregistration.reconciliation.service;
import com.weaponsregistration.core.service.UnitScopeGuard;import jakarta.persistence.EntityManager;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.server.ResponseStatusException;
@Component public class InventoryCountUnitScopeGuard implements UnitScopeGuard{private final EntityManager em;public InventoryCountUnitScopeGuard(EntityManager em){this.em=em;}public void validateOrganizationChange(long unit,long organization){long n=em.createQuery("select count(c) from InventoryCount c where c.unit.id=:u and c.organization.id<>:o",Long.class).setParameter("u",unit).setParameter("o",organization).getSingleResult();if(n>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"The unit has inventory count history.");}}
